/*
 * CozyNook sprite engine
 * ----------------------
 * Draws the layered pixel-art character and the animated cat onto small
 * <canvas> elements, which CSS scales up with crisp "pixelated" rendering.
 *
 * The sprite sheets live in assets/sprites/ and are generated by
 * tools/build_sprites.py.  Colours that the player can customise (skin,
 * hair, outfit, cat coat) are "key" colours in the PNGs and get swapped here.
 *
 * Public API (window.CozySprites):
 *   setLook(state)            update character + cat look from the save state
 *   portrait(element)         draw a small head portrait into an element
 *   catPreview(coatKey)       canvas showing a cat in the given coat
 *   CAT_COATS                 list of [key, label] coat choices
 */
(function () {
  'use strict';
  var META = window.COZY_SPRITE_META;
  if (!META) { console.warn('CozyNook: sprite metadata missing'); return; }

  var BASE = 'assets/sprites/';
  var CW = META.cell[0], CH = META.cell[1], COLS = META.cols;
  var KW = META.cat.cell[0], KH = META.cat.cell[1];
  var IW = META.icons.cell[0];

  // ---------------------------------------------------------------- colour helpers
  function rgb(hex) {
    hex = hex.replace('#', '');
    if (hex.length === 3) hex = hex.split('').map(function (c) { return c + c; }).join('');
    return [parseInt(hex.slice(0, 2), 16), parseInt(hex.slice(2, 4), 16), parseInt(hex.slice(4, 6), 16)];
  }
  function mix(a, b, t) {
    var A = rgb(a), B = rgb(b);
    return '#' + A.map(function (v, i) {
      return Math.round(v + (B[i] - v) * t).toString(16).padStart(2, '0');
    }).join('');
  }
  var shade = function (c, t) { return mix(c, '#3a2046', t); };   // purple-ish shadows look nicer than grey
  var light = function (c, t) { return mix(c, '#fff4dc', t); };

  var CAT_COATS = [
    ['ginger', 'Ginger tabby', { f: '#f2a65a', F: '#c97a3a', g: '#ffd09a', d: '#b0612c', z: '#fff3e2', Z: '#e8d2bd' }],
    ['grey', 'Grey tabby', { f: '#a9adbd', F: '#7d8197', g: '#ccd0dc', d: '#676b82', z: '#f6f2ec', Z: '#d8d3cc' }],
    ['tuxedo', 'Tuxedo', { f: '#4a4459', F: '#332e40', g: '#6a6380', d: '#332e40', z: '#fff6ea', Z: '#e0d2c4' }],
    ['snow', 'Snowball', { f: '#fbf1e4', F: '#e3cfb8', g: '#ffffff', d: '#f0d9c0', z: '#ffffff', Z: '#efe3d6' }],
    ['cocoa', 'Cocoa', { f: '#8f5d45', F: '#68412f', g: '#ad7c61', d: '#5c3828', z: '#f4dcc4', Z: '#d8bea4' }],
    ['blue', 'Blue moon', { f: '#7d8fb8', F: '#5b6b94', g: '#a3b3d6', d: '#56658c', z: '#eef0fb', Z: '#cfd4e8' }]
  ];

  function characterPalette(st) {
    var skin = st.skin || '#efbd9d', hair = st.hair || '#67483d', cloth = st.outfit || '#91a477';
    return {
      s: skin, S: shade(skin, 0.22), q: light(skin, 0.4), b: mix(skin, '#e8607a', 0.45),
      h: hair, H: shade(hair, 0.32), l: light(hair, 0.22),
      c: cloth, C: shade(cloth, 0.26), L: light(cloth, 0.3)
    };
  }
  function catPalette(key) {
    for (var i = 0; i < CAT_COATS.length; i++) if (CAT_COATS[i][0] === key) return CAT_COATS[i][2];
    return CAT_COATS[0][2];
  }

  // ---------------------------------------------------------------- image loading + recolouring
  var images = {}, loaded = 0, NEED = 3, onReady = [];
  ['character-layers', 'cat', 'emote-icons'].forEach(function (name) {
    var img = new Image();
    img.onload = function () { loaded++; if (loaded === NEED) onReady.forEach(function (f) { f(); }); };
    img.onerror = function () { console.warn('CozyNook: could not load sprite sheet ' + name); };
    img.src = BASE + name + '.png';
    images[name] = img;
  });
  function ready() { return loaded === NEED; }

  var recolourCache = {};
  // Returns a canvas copy of the sheet with key colours swapped.
  // If the browser blocks pixel access (e.g. opening the file directly from
  // disk) we fall back to the original sheet, which uses the default colours.
  function recoloured(sheetName, palette) {
    var cacheKey = sheetName + JSON.stringify(palette);
    if (recolourCache[cacheKey]) return recolourCache[cacheKey];
    var img = images[sheetName];
    var c = document.createElement('canvas');
    c.width = img.naturalWidth; c.height = img.naturalHeight;
    var ctx = c.getContext('2d');
    ctx.drawImage(img, 0, 0);
    try {
      var data = ctx.getImageData(0, 0, c.width, c.height);
      var px = data.data, map = {};
      Object.keys(palette).forEach(function (k) {
        if (!META.keys[k]) return;
        var from = rgb(META.keys[k]);
        map[(from[0] << 16) | (from[1] << 8) | from[2]] = rgb(palette[k]);
      });
      for (var i = 0; i < px.length; i += 4) {
        if (!px[i + 3]) continue;
        var to = map[(px[i] << 16) | (px[i + 1] << 8) | px[i + 2]];
        if (to) { px[i] = to[0]; px[i + 1] = to[1]; px[i + 2] = to[2]; }
      }
      ctx.putImageData(data, 0, 0);
    } catch (err) {
      c = img;
    }
    recolourCache[cacheKey] = c;
    return c;
  }

  function layerXY(name) {
    var i = META.layers[name];
    if (i === undefined) return null;
    return [(i % COLS) * CW, Math.floor(i / COLS) * CH];
  }

  // ---------------------------------------------------------------- character drawing
  var look = { gender: 'girl', emote: 'happy', outfitStyle: 'hoodie', hairStyle: 'default', accessory: 'none' };

  function layerList(blink) {
    var g = look.gender === 'boy' ? 'boy' : 'girl';
    var hs = look.hairStyle || 'default';
    var hk = hs === 'default' ? 'default-' + g : hs;
    var emote = look.emote || 'happy';
    var faceName = blink ? 'face-' + emote + '-blink' : 'face-' + emote + (g === 'girl' ? '-girl' : '');
    var list = ['hairback-' + hk, 'body', 'outfit-' + (look.outfitStyle || 'hoodie'), faceName, 'hairfront-' + hk];
    var acc = look.accessory;
    if (acc && acc !== 'none') {
      // the cap sits over the hair; hide the hair top under it for a cleaner look
      list.push('acc-' + acc);
    }
    return list;
  }

  // Draws the character at (ox, oy).  headDy pushes the head down (breathing).
  function drawCharacter(ctx, ox, oy, blink, headDy) {
    var sheet = recoloured('character-layers', characterPalette(look));
    var SPLIT = 22;   // rows above this belong to the head
    layerList(blink).forEach(function (name) {
      var p = layerXY(name);
      if (!p) return;
      // body / lower half
      ctx.drawImage(sheet, p[0], p[1] + SPLIT, CW, CH - SPLIT, ox, oy + SPLIT, CW, CH - SPLIT);
      // head / upper half
      ctx.drawImage(sheet, p[0], p[1], CW, SPLIT, ox, oy + headDy, CW, SPLIT);
    });
  }

  function drawIcon(ctx, emote, x, y) {
    var idx = META.icons.order.indexOf(emote);
    if (idx < 0) return;
    // little speech bubble behind the icon
    ctx.fillStyle = '#3a2630';
    ctx.fillRect(x + 1, y, IW + 2, IW + 4);
    ctx.fillRect(x, y + 1, IW + 4, IW + 2);
    ctx.fillStyle = '#fff8ec';
    ctx.fillRect(x + 1, y + 1, IW + 2, IW + 2);
    ctx.fillStyle = '#3a2630';
    ctx.fillRect(x + 2, y + IW + 4, 2, 2);
    ctx.fillRect(x + 1, y + IW + 6, 1, 1);
    ctx.drawImage(images['emote-icons'], idx * IW, 0, IW, IW, x + 2, y + 2, IW, IW);
  }

  // ---------------------------------------------------------------- room character widget
  var CHAR_W = 46, CHAR_H = 62, CHAR_OX = 3, CHAR_OY = 16;
  var charCanvas = null, charState = { breathe: 0, blinkUntil: 0, nextBlink: 0, hop: [], iconBob: 0 };

  function ensureCharacterCanvas() {
    var host = document.getElementById('roomCharacter');
    if (!host) return null;
    if (!charCanvas || charCanvas.parentNode !== host) {
      charCanvas = document.createElement('canvas');
      charCanvas.width = CHAR_W; charCanvas.height = CHAR_H;
      charCanvas.className = 'sprite-canvas';
      host.appendChild(charCanvas);
      host.addEventListener('click', function () { hopCharacter(); });
    }
    return charCanvas;
  }
  function hopCharacter() { charState.hop = [-2, -4, -5, -4, -2, 0, -1, 0]; }

  function renderCharacter(now) {
    var c = ensureCharacterCanvas();
    if (!c || !ready()) return;
    var ctx = c.getContext('2d');
    ctx.clearRect(0, 0, CHAR_W, CHAR_H);
    if (now > charState.nextBlink) {
      charState.blinkUntil = now + 150;
      charState.nextBlink = now + 2400 + Math.random() * 3200;
    }
    var blink = now < charState.blinkUntil;
    var headDy = Math.floor(now / 700) % 2;
    var hopY = charState.hop.length ? charState.hop.shift() : 0;
    // soft floor shadow
    ctx.fillStyle = 'rgba(58,38,48,.22)';
    ctx.fillRect(CHAR_OX + 8, CHAR_OY + CH - 2, 16, 2);
    ctx.fillRect(CHAR_OX + 6, CHAR_OY + CH - 1, 20, 1);
    drawCharacter(ctx, CHAR_OX, CHAR_OY + hopY, blink, hopY ? 0 : headDy);
    var bob = Math.floor(now / 500) % 2;
    drawIcon(ctx, look.emote || 'happy', 28, 1 + bob + Math.min(0, hopY));
  }

  // ---------------------------------------------------------------- cat widget
  var CAT_W = 40, CAT_H = 48, CAT_OX = 4, CAT_OY = 18;
  var catCanvas = null;
  var cat = { mode: 'sit', since: 0, until: 0, nextBlink: 0, blinkUntil: 0, coat: 'ginger', hop: [], hearts: [] };

  function frameXY(name) {
    var i = META.cat.frames.indexOf(name);
    return i < 0 ? 0 : i * KW;
  }
  function ensureCatCanvas() {
    var host = document.getElementById('sleepyCat');
    if (!host) return null;
    if (!catCanvas || catCanvas.parentNode !== host) {
      catCanvas = document.createElement('canvas');
      catCanvas.width = CAT_W; catCanvas.height = CAT_H;
      catCanvas.className = 'sprite-canvas';
      host.appendChild(catCanvas);
      host.addEventListener('click', petCat);
      host.addEventListener('keydown', function (e) { if (e.key === 'Enter' || e.key === ' ') petCat(); });
    }
    return catCanvas;
  }
  function petCat() {
    var now = performance.now();
    cat.mode = 'happy'; cat.since = now; cat.until = now + 1600;
    cat.hop = [-2, -4, -4, -2, 0, 0, -2, -3, -2, 0];
    cat.hearts.push({ x: 6 + Math.random() * 8, born: now }, { x: 18 + Math.random() * 8, born: now + 250 });
  }
  function drawHeart(ctx, x, y) {
    ctx.fillStyle = '#3a2630';
    ctx.fillRect(x, y + 1, 7, 3); ctx.fillRect(x + 1, y, 2, 5); ctx.fillRect(x + 4, y, 2, 5);
    ctx.fillRect(x + 2, y + 4, 3, 2); ctx.fillRect(x + 3, y + 6, 1, 1);
    ctx.fillStyle = '#ec5f7e';
    ctx.fillRect(x + 1, y + 1, 2, 3); ctx.fillRect(x + 4, y + 1, 2, 3); ctx.fillRect(x + 2, y + 2, 3, 3); ctx.fillRect(x + 3, y + 5, 1, 1);
    ctx.fillStyle = '#ffffff';
    ctx.fillRect(x + 1, y + 1, 1, 1);
  }
  function drawZ(ctx, x, y, s) {
    ctx.fillStyle = '#4f97c2';
    ctx.fillRect(x, y, s, 1); ctx.fillRect(x, y + s - 1, s, 1);
    for (var i = 1; i < s - 1; i++) ctx.fillRect(x + s - 1 - i, y + i, 1, 1);
  }

  function renderCat(now) {
    var c = ensureCatCanvas();
    if (!c || !ready()) return;
    var ctx = c.getContext('2d');
    ctx.clearRect(0, 0, CAT_W, CAT_H);
    if (!cat.since) { cat.since = now; cat.until = now + 18000 + Math.random() * 12000; }

    // simple behaviour loop: sit and look around -> curl up for a nap -> wake up
    if (cat.mode === 'happy' && now > cat.until) { cat.mode = 'sit'; cat.since = now; cat.until = now + 15000 + Math.random() * 15000; }
    else if (cat.mode === 'sit' && now > cat.until) { cat.mode = 'sleep'; cat.since = now; cat.until = now + 12000 + Math.random() * 10000; }
    else if (cat.mode === 'sleep' && now > cat.until) { cat.mode = 'sit'; cat.since = now; cat.until = now + 18000 + Math.random() * 12000; }

    var frame;
    if (cat.mode === 'sleep') {
      frame = Math.floor(now / 900) % 2 ? 'loaf1' : 'loaf0';
    } else if (cat.mode === 'happy') {
      frame = Math.floor(now / 160) % 2 ? 'happy2' : 'happy';
    } else {
      if (now > cat.nextBlink) { cat.blinkUntil = now + 160; cat.nextBlink = now + 2000 + Math.random() * 3500; }
      var t = Math.floor(now / 420) % 6;
      frame = now < cat.blinkUntil ? 'blink' : ['sit0', 'sit0', 'sit1', 'sit2', 'sit2', 'sit1'][t];
    }
    var hopY = cat.hop.length ? cat.hop.shift() : 0;
    // shadow
    ctx.fillStyle = 'rgba(58,38,48,.2)';
    ctx.fillRect(CAT_OX + 3, CAT_OY + KH - 2, 22, 2);
    var sheet = recoloured('cat', catPalette(cat.coat));
    ctx.drawImage(sheet, frameXY(frame), 0, KW, KH, CAT_OX, CAT_OY + hopY, KW, KH);

    if (cat.mode === 'sleep') {
      var phase = ((now - cat.since) / 1400) % 3;
      if (phase > 0.4) drawZ(ctx, 27, 20 - Math.floor(phase * 2), 4);
      if (phase > 1.4) drawZ(ctx, 32, 12 - Math.floor(phase * 2), 5);
    }
    cat.hearts = cat.hearts.filter(function (h) { return now - h.born < 1300; });
    cat.hearts.forEach(function (h) {
      var age = now - h.born;
      if (age < 0) return;
      drawHeart(ctx, Math.round(h.x), Math.round(12 - age / 110));
    });
  }

  // ---------------------------------------------------------------- portrait + previews
  function portrait(el) {
    if (!el) return;
    var c = el.querySelector('canvas.portrait-canvas');
    if (!c) {
      el.textContent = '';
      c = document.createElement('canvas');
      c.className = 'portrait-canvas sprite-canvas';
      c.width = 26; c.height = 24;
      el.appendChild(c);
    }
    var draw = function () {
      var ctx = c.getContext('2d');
      ctx.clearRect(0, 0, 26, 24);
      var tmp = document.createElement('canvas');
      tmp.width = CW; tmp.height = CH;
      drawCharacter(tmp.getContext('2d'), 0, 0, false, 0);
      ctx.drawImage(tmp, 3, 0, 26, 24, 0, 1, 26, 24);
    };
    if (ready()) draw(); else onReady.push(draw);
  }

  function catPreview(coat) {
    var c = document.createElement('canvas');
    c.width = KW; c.height = KH;
    c.className = 'sprite-canvas cat-preview';
    var draw = function () {
      c.getContext('2d').drawImage(recoloured('cat', catPalette(coat)), frameXY('sit0'), 0, KW, KH, 0, 0, KW, KH);
    };
    if (ready()) draw(); else onReady.push(draw);
    return c;
  }

  // ---------------------------------------------------------------- main loop
  function tick() {
    if (document.hidden) return;
    var now = performance.now();
    renderCharacter(now);
    renderCat(now);
  }
  setInterval(tick, 80);

  function setLook(st) {
    look = {
      gender: st.gender, emote: st.emote, outfitStyle: st.outfitStyle, hairStyle: st.hairStyle,
      accessory: st.accessory, skin: st.skin, hair: st.hair, outfit: st.outfit
    };
    cat.coat = st.catCoat || 'ginger';
    tick();
  }

  window.CozySprites = {
    setLook: setLook, portrait: portrait, catPreview: catPreview, petCat: petCat, hop: hopCharacter,
    CAT_COATS: CAT_COATS.map(function (c) { return [c[0], c[1]]; })
  };
})();
